cardCss:
.card {
  font-family: "Noto Serif SC", "Songti SC", "STSong", serif;
  font-size: 16px;
  line-height: 1.9;
  color: #1a1a1a;
  background: #ffffff;
  text-align: left;
  padding: 8px;
}
.qz-top-line {
  height: 3px;
  background: linear-gradient(90deg, #0e7490, #06b6d4);
  border-radius: 2px;
  margin: -8px -8px 20px -8px;
}
.qz-kicker {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 3px;
  color: #0e7490;
  margin-bottom: 14px;
  display: block;
}
.qz-question {
  font-size: 17px;
  font-weight: 700;
  line-height: 1.7;
  margin-bottom: 20px;
  padding-bottom: 14px;
  border-bottom: 1px solid #e2e8f0;
}
.qz-options { margin: 0 0 20px 0; }
.option {
  display: flex;
  align-items: flex-start;
  padding: 10px 14px;
  margin: 0 0 8px 0;
  border: 1px solid #e2e8f0;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
  font-size: 15px;
  line-height: 1.7;
}
.option:hover {
  border-color: #0e7490;
  background: #f0fdfa;
}
.opt-badge {
  display: inline-block;
  min-width: 28px;
  height: 28px;
  line-height: 28px;
  text-align: center;
  font-weight: 700;
  font-size: 13px;
  color: #0e7490;
  border: 1px solid #0e7490;
  border-radius: 4px;
  margin-right: 12px;
  flex-shrink: 0;
}
.opt-text { flex: 1; }
.opt-radio { display: none; }
.option:has(.opt-radio:checked) {
  border-color: #0e7490;
  border-width: 2px;
  background: #ecfeff;
  padding: 9px 13px;
}
.option:has(.opt-radio:checked) .opt-badge {
  background: #0e7490;
  color: #fff;
}
.quiz-controls { margin: 16px 0; }
.quiz-controls input[type="radio"] { display: none; }
.quiz-controls label {
  display: inline-block;
  padding: 8px 24px;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  border-radius: 4px;
  transition: all 0.2s;
  margin-right: 8px;
}
label[for^="submit"] {
  background: #0e7490;
  color: #fff;
}
label[for^="submit"]:hover { background: #155e75; }
label[for^="reset"] {
  background: #f1f5f9;
  color: #475569;
  border: 1px solid #cbd5e1;
}
label[for^="reset"]:hover { background: #e2e8f0; }
.quiz-card:has(#submit-check:checked) .option.is-correct {
  border-color: #059669;
  border-width: 2px;
  background: #d1fae5;
  padding: 9px 13px;
}
.quiz-card:has(#submit-check:checked) .option.is-correct .opt-badge {
  background: #059669;
  color: #fff;
}
.quiz-card:has(#submit-check:checked) .option:has(.opt-radio:checked):not(.is-correct) {
  border-color: #dc2626;
  border-width: 2px;
  background: #fef2f2;
  padding: 9px 13px;
}
.quiz-card:has(#submit-check:checked) .option:has(.opt-radio:checked):not(.is-correct) .opt-badge {
  background: #dc2626;
  color: #fff;
}
.quiz-card:has(#submit-check:checked) .option:not(.is-correct):not(:has(.opt-radio:checked)) {
  opacity: 0.4;
}
.quiz-card:has(#submit-check:checked) .answer-reveal {
  display: block;
  animation: fadeIn 0.3s ease;
}
.quiz-card:has(#reset-radio:checked) .answer-reveal { display: none; }
.answer-reveal {
  display: none;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 2px solid #0e7490;
}
.ans-badge {
  display: inline-block;
  font-size: 12px;
  font-weight: 700;
  color: #0e7490;
  border: 1px solid #0e7490;
  padding: 2px 10px;
  border-radius: 3px;
  margin-bottom: 8px;
}
.ans-text {
  font-size: 17px;
  font-weight: 700;
  color: #0e7490;
  margin-bottom: 16px;
}
.exp-block {
  font-size: 15px;
  line-height: 1.9;
  color: #334155;
  margin-top: 12px;
}
.exp-block b { color: #0e7490; }
.highlight {
  background: #cffafe;
  color: #0e7490;
  font-weight: 700;
  padding: 0 4px;
  border-radius: 2px;
}
.law-ref {
  color: #0e7490;
  font-weight: 700;
  text-decoration: underline;
  text-decoration-color: #0e7490;
  text-underline-offset: 3px;
}
.mnemonic {
  background: #ecfeff;
  border: 1px solid #0e7490;
  border-left: 4px solid #0e7490;
  border-radius: 4px;
  padding: 12px 16px;
  margin: 12px 0;
  font-size: 15px;
  color: #155e75;
}
.note-block {
  background: #fefce8;
  border: 1px solid #ca8a04;
  border-left: 4px solid #ca8a04;
  border-radius: 4px;
  padding: 12px 16px;
  margin: 12px 0;
  font-size: 14px;
  color: #713f12;
}
.qz-source {
  font-size: 12px;
  color: #94a3b8;
  margin-top: 16px;
  padding-top: 10px;
  border-top: 1px dashed #e2e8f0;
}
.card-back .option { cursor: default; }
.card-back .option.is-correct {
  border-color: #059669;
  border-width: 2px;
  background: #d1fae5;
}
.card-back .option.is-correct .opt-badge {
  background: #059669;
  color: #fff;
}
.card-back .option:not(.is-correct) { opacity: 0.5; }
.card-back .quiz-controls { display: none; }
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.anki-audio, .anki-video { display: block; width: 100%; max-width: 100%; margin: 0.5rem 0; }
.anki-media-missing { display: block; margin: 0.35rem 0; color: #9f1239; font-size: 0.875rem; }
.anki-math-source,
.anki-math-rendered {
  display: inline-block;
  max-width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  vertical-align: middle;
  -webkit-overflow-scrolling: touch;
}
.anki-math-source {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  white-space: pre-wrap;
}
.anki-math-source[data-anki-math="display"],
.anki-math-rendered[data-anki-math="display"] {
  display: block;
  margin: 0.75rem 0;
  text-align: center;
}
.anki-math-rendered math {
  max-width: 100%;
}
@media (max-width: 767px) {
  .anki-math-source,
  .anki-math-rendered {
    width: 100%;
    max-width: 100%;
    text-align: left;
  }
}
.miki-apkg-card { box-sizing: border-box; width: 100%; max-width: 980px; margin: 0 auto; color: #111827; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif; line-height: 1.85; }
.miki-apkg-card * { box-sizing: border-box; }
.miki-apkg-topbar { display: flex; justify-content: center; gap: 12px; margin: 6px 0 22px; }
.miki-apkg-tab { display: inline-flex; align-items: center; gap: 8px; padding: 8px 16px; border-radius: 12px; background: #f4f7fb; color: #2563eb; font-weight: 800; }
.miki-apkg-badge { min-width: 20px; height: 20px; padding: 0 7px; border-radius: 999px; display: inline-flex; align-items: center; justify-content: center; background: #ef4444; color: #fff; font-size: 12px; font-weight: 900; }
.miki-apkg-control { display: flex; justify-content: center; margin: -8px 0 24px; }
.miki-apkg-control-pill { border: 0; border-radius: 999px; padding: 9px 22px; background: #39d486; color: #fff; font-weight: 900; }
.miki-apkg-question { margin: 0 auto 24px; max-width: 980px; font-size: 16px; font-weight: 750; line-height: 2; }
.miki-apkg-question-type { color: #007aff; font-weight: 900; margin-right: 4px; }
.miki-apkg-options { margin: 22px auto 18px; max-width: 980px; display: grid; gap: 12px; }
.miki-apkg-option { display: flex; align-items: flex-start; gap: 10px; width: 100%; min-height: 46px; border: 1.5px solid #1f2937; border-radius: 6px; padding: 10px 14px; background: #fff; color: #111827; font-size: 15px; font-weight: 700; cursor: pointer; }
.miki-apkg-option input { flex: 0 0 auto; margin-top: 6px; }
.miki-apkg-option-letter { flex: 0 0 auto; font-weight: 900; }
.miki-apkg-option-text { flex: 1 1 auto; }
.miki-apkg-source-pills { display: flex; flex-wrap: wrap; gap: 8px; margin: 18px auto 0; max-width: 980px; }
.miki-apkg-pill { display: inline-flex; align-items: center; border: 1.5px solid #1e90ff; border-radius: 5px; background: #eff6ff; padding: 6px 10px; color: #007aff; font-size: 14px; font-weight: 850; line-height: 1.55; }
.miki-apkg-back { max-width: 980px; margin: 0 auto; }
.miki-apkg-back-title { margin: 0 0 12px; font-size: 15px; font-weight: 900; color: #007aff; }
.miki-apkg-section { margin: 14px 0; padding: 14px 16px; border-radius: 14px; background: #f8fafc; border: 1px solid #e5e7eb; }
.miki-apkg-section h3 { margin: 0 0 8px; font-size: 14px; color: #2563eb; }
.miki-apkg-section-content { font-size: 15px; line-height: 1.85; }
.miki-anki-readable-fallback { padding: 16px; color: #111827; line-height: 1.85; white-space: pre-wrap; }
